package com.eventos.api.security;
import io.jsonwebtoken.*; import io.jsonwebtoken.security.Keys; import org.springframework.beans.factory.annotation.Value; import org.springframework.stereotype.Service; import java.nio.charset.StandardCharsets; import java.util.*;
@Service public class JwtService { private final byte[] key; private final long expiration; public JwtService(@Value("${app.jwt.secret}") String secret,@Value("${app.jwt.expiration-ms}") long expiration){this.key=secret.getBytes(StandardCharsets.UTF_8);this.expiration=expiration;} public String create(Long id,String email){return Jwts.builder().setSubject(id.toString()).claim("email",email).setIssuedAt(new Date()).setExpiration(new Date(System.currentTimeMillis()+expiration)).signWith(Keys.hmacShaKeyFor(key),SignatureAlgorithm.HS256).compact();} public Long adminId(String token){return Long.valueOf(Jwts.parserBuilder().setSigningKey(key).build().parseClaimsJws(token).getBody().getSubject());} }
